138	 /* ------------------------- Tín hiệu từ hai trạng thái liên tiếp ------------------------- */
139	 /* Trạng thái lấy mẫu của một dù. Ba trường cuối tùy chọn (thiếu thì coi là 0 / false): bộ lọc acc, vy và cờ đã có tốc độ hợp lệ */
140	 export interface PlTrack { x: number; y: number; z: number; speed: number; has: boolean; acc?: number; vy?: number; hasSpeed?: boolean }
141	 
142	-const SMOOTH_S = 0.15;     // s hằng số thời gian lọc một cực cho acc / vy (ước lượng)
143	-const TELEPORT_MS = 300;   // m/s — nhanh hơn mức này coi là nhảy vị trí (vào phòng, sửa lỗi mạng), bỏ qua mẫu (ước lượng)
144	-
145	 /* Tính tín hiệu cho mọi dù (của mình lẫn người khác, đều từ vị trí + bank). Không cấp phát; prev được cập nhật tại chỗ.
146	    turnInput (tùy chọn, dù của mình): −1/0/1 như GliderInput.turn (+1 = trái); trộn nửa đường để tay đi trước thân */
147	 export function plSignals(out: PlSignals, prev: PlTrack, x: number, y: number, z: number, bank: number, dt: number, wind: number, turnInput?: number): void {
148	-  const E = CONFIG.explore;
149	+  const E = CONFIG.explore, SG = E.pilot.signal;   // SG.smooth: hằng số thời gian lọc acc / vy (s); SG.teleport: m/s, nhanh hơn coi là nhảy vị trí (vào phòng, sửa lỗi mạng), bỏ mẫu
150	   out.wind = clamp(fin(wind), 0, 1);
151	   let turn = clampSym(bank / E.bankMax);
152	-  if (turnInput !== undefined && Number.isFinite(turnInput)) turn += (clampSym(turnInput) - turn) * 0.5;
153	+  if (turnInput !== undefined && Number.isFinite(turnInput)) turn += (clampSym(turnInput) - turn) * SG.turnMix;
154	   out.turn = turn;
155	   if (!Number.isFinite(x + y + z) || !(dt > 0) || !Number.isFinite(dt)) { out.acc = clampSym(prev.acc || 0); out.vy = clampSym(prev.vy || 0); return; }   // mẫu xấu: giữ giá trị lọc cũ
156	   if (!prev.has) { prev.x = x; prev.y = y; prev.z = z; prev.speed = 0; prev.has = true; prev.hasSpeed = false; prev.acc = 0; prev.vy = 0; out.acc = 0; out.vy = 0; return; }
157	   const dx = x - prev.x, dz = z - prev.z, sp = Math.sqrt(dx * dx + dz * dz) / dt, vyRaw = (y - prev.y) / dt;
158	   let accRaw = 0, vyN = 0;
159	-  if (Math.abs(sp) > TELEPORT_MS || Math.abs(vyRaw) > TELEPORT_MS) { prev.hasSpeed = false; }   // nhảy vị trí: bỏ mẫu, bộ lọc giữ nguyên
160	+  if (Math.abs(sp) > SG.teleport || Math.abs(vyRaw) > SG.teleport) { prev.hasSpeed = false; }   // nhảy vị trí: bỏ mẫu, bộ lọc giữ nguyên
161	   else {
162	     if (prev.hasSpeed) accRaw = clampSym((sp - prev.speed) / dt / E.speedAccel);
163	     vyN = clampSym(vyRaw / E.climbRate);
164	     prev.speed = sp; prev.hasSpeed = true;
165	-    const a = 1 - Math.exp(-dt / SMOOTH_S);
166	+    const a = 1 - Math.exp(-dt / SG.smooth);
167	     prev.acc = (prev.acc || 0) + (accRaw - (prev.acc || 0)) * a;
